// CPR/First Aid Practice Test 3. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering different situations from Practice Tests 1 and 2.
import {q, mix} from './q.js';
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-3',
 event:'CPR/First Aid',
 title:'Practice Test 3',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:mix([
  q(GEN,'A bystander with no CPR training sees an adult collapse and stop breathing normally. After calling 911, what should the bystander do?','Give Hands-Only CPR, pushing hard and fast',['Wait for EMS without touching the person','Give rescue breaths only, every 6 seconds','Check for a pulse for at least 30 seconds'],'A','Untrained bystanders should give compression-only CPR for adults. It is easy to learn and still circulates oxygen already in the blood.',AHA_BLS),
  q(GEN,'Why should pauses in chest compressions be kept as short as possible?','Blood flow to the heart drops and rebuilds slowly',['Pauses cause the AED to lose its stored charge','Pauses make the rescue breaths ineffective','The patient’s pulse becomes impossible to find'],'B','Coronary perfusion pressure builds with each compression and falls almost immediately in a pause, so frequent pauses reduce blood flow to the heart.',AHA_BLS),
  q(GEN,'In the AHA in-hospital Chain of Survival, which link comes first?','Early recognition and prevention',['Rapid defibrillation by staff','High-quality CPR','Post–cardiac arrest care'],'C','In hospitals, many arrests are preceded by warning signs, so the chain begins with surveillance, early recognition and prevention.',AHA_BLS),
  q(GEN,'What is the main benefit of using a CPR feedback device during resuscitation?','It shows compression rate and depth in real time',['It delivers a shock as soon as VF is detected','It measures the patient’s blood glucose','It replaces the need to check for breathing'],'D','Rescuers often misjudge their own performance; feedback devices help keep compressions within the recommended rate and depth.',AHA_BLS),
  q(CPR,'Two rescuers are performing CPR on a 5-year-old. Which compression-to-ventilation ratio should they use?','15:2',['30:2','5:1','30:1'],'A','For children and infants, two rescuers use 15:2 to provide more ventilation; a single rescuer uses 30:2 for all ages.',AHA_BLS),
  q(CPR,'Where should the hands be placed for adult chest compressions?','On the lower half of the breastbone',['On the upper third of the breastbone','Over the left side of the chest','On the xiphoid process at the bottom'],'B','Compressing the lower half of the sternum squeezes the heart most effectively and avoids the xiphoid process and ribs.',AHA_BLS),
  q(CPR,'About how deep should compressions be for an infant?','About 1½ inches (4 cm)',['About ½ inch (1 cm)','About 2½ inches (6 cm)','About 3 inches (8 cm)'],'C','Infant compressions should be at least one-third the depth of the chest, which is about 1½ inches.',AHA_BLS),
  q(CPR,'Where should a healthcare provider check for a pulse in an unresponsive infant?','The brachial artery of the upper arm',['The carotid artery in the side of the neck','The radial artery at the wrist','The temporal artery near the ear'],'D','An infant’s short neck makes the carotid hard to find, so the brachial pulse is checked; for a child, the carotid or femoral is used.',AHA_BLS),
  q(CPR,'A lone rescuer without a phone finds an unresponsive, non-breathing infant after an unwitnessed collapse. When should the rescuer leave to call for help?','After about 2 minutes of CPR',['Before starting any CPR','After 30 seconds of CPR','Only after the infant begins breathing'],'A','Pediatric arrests are usually caused by breathing problems, so about 2 minutes of CPR comes first; a sudden witnessed collapse calls for help right away.',AHA_BLS),
  q(CPR,'Which situation allows a rescuer to stop CPR?','The person starts breathing normally',['The rescuer has done CPR for 5 minutes','A family member asks the rescuer to stop','The person’s skin feels cool to the touch'],'B','Continue until the person shows signs of life, an AED or trained help takes over, the scene becomes unsafe or you are too exhausted to continue.',ARC_BLS),
  q(AED,'An AED arrives for a 6-year-old in cardiac arrest, but only adult pads are available. What should the rescuer do?','Use adult pads, front and back if they would touch',['Wait for pediatric pads before using the AED','Cut the adult pads in half to fit the chest','Do CPR only, since adult pads can never be used'],'C','Adult pads deliver a higher dose, but a shock is better than none. Pads must not touch, so front-and-back placement may be needed.',AHA_BLS),
  q(AED,'A man in cardiac arrest has a very hairy chest, and the AED prompts “check pads.” What should the rescuer do?','Remove the hair, then apply new pads',['Press the pads down harder and ignore it','Place the pads on the abdomen instead','Switch to giving rescue breaths only'],'D','Hair prevents good contact. Ripping off a pad removes hair, and a second set or a razor in the AED kit allows a proper connection.',ARC_BLS),
  q(AED,'An adult in cardiac arrest was pulled from the rain, and the chest is wet. What should be done before applying AED pads?','Quickly wipe the chest dry',['Pour alcohol on the chest','Place the pads over the wet shirt','Wait until the chest dries by itself'],'A','Water can conduct the shock across the skin, reducing the energy that reaches the heart. Dry the chest quickly so the pads stick.',ARC_BLS),
  q(AED,'Why does survival from witnessed VF arrest fall rapidly with each minute before defibrillation?','VF decays into asystole, which can’t be shocked',['The AED battery drains every minute','Compressions become illegal after 5 minutes','Rescue breaths stop working after 3 minutes'],'B','Without CPR, survival drops about 7–10% per minute. CPR slows the decline, but early defibrillation is what stops VF.',AHA_BLS),
  q(ADV,'Once an endotracheal tube is placed during adult CPR, how should compressions be given?','Continuously, with no pauses for breaths',['In cycles of 30, pausing for 2 breaths','In cycles of 15, pausing for 2 breaths','Only after each breath has been completed'],'C','With an advanced airway, compressions continue without pauses while one breath is given every 6 seconds, improving compression fraction.',AHA_BLS),
  q(ADV,'Which device is a supraglottic advanced airway?','Laryngeal mask airway',['Nasal cannula with oxygen','Simple face mask','Oropharyngeal airway'],'D','Supraglottic airways such as the LMA sit above the glottis; oral and nasal airways only keep the tongue from blocking the airway.',AHA_BLS),
  q(RB,'A child has a pulse but is not breathing normally. How often should rescue breaths be given?','1 breath every 2–3 seconds',['1 breath every 6 seconds','1 breath every 10 seconds','2 breaths every 30 seconds'],'A','Children and infants with a pulse receive 20–30 breaths per minute; check the pulse about every 2 minutes and start CPR if it falls below 60 with poor perfusion.',AHA_BLS),
  q(RB,'Air is going into a patient’s stomach during rescue breathing. What is the most likely cause?','Breaths that are too large or forceful',['Breaths that last about 1 second','Tilting the head and lifting the chin','Watching for the chest to rise'],'B','Give only enough air to make the chest rise. Excess volume or speed opens the esophagus, causing gastric inflation and vomiting.',AHA_BLS),
  q(CH,'A choking adult is too large for the rescuer to reach around the abdomen. What should the rescuer do?','Give chest thrusts instead of abdominal thrusts',['Give back blows only until the object comes out','Perform blind finger sweeps of the throat','Have the person lie down and drink water'],'C','Chest thrusts are used when the rescuer cannot encircle the abdomen, such as with obesity or late pregnancy.',ARC_FA),
  q(CH,'You are alone and choking, unable to speak or cough. Which action is recommended?','Thrust yourself against a chair back',['Lie flat on the floor and wait for help','Drink water to wash down the object','Lean back and slap your own chest hard'],'D','Self-administered thrusts with your fist or against a firm object such as a chair back can expel the obstruction; call 911 if you can.',ARC_FA),
  q(BASIC,'What are the three emergency action steps taught by the American Red Cross?','Check, Call, Care',['Call, Carry, Comfort','Assess, Airway, Activate','Stop, Look, Listen'],'A','Check the scene and the person, Call 911 or the local emergency number, then Care for the person until help arrives.',ARC_FA),
  q(BASIC,'When should a first aider move an injured person before EMS arrives?','When there is immediate danger, such as fire',['Whenever the person asks to be more comfortable','Before checking whether the scene is safe','Any time a spinal injury is possible'],'B','Moving an injured person can worsen injuries, so it is done only when the scene threatens life or to reach a more seriously injured person.',ARC_FA),
  q(BASIC,'A 7-year-old is injured at a park, and no parent or guardian can be found. How is consent handled?','Consent is implied in this emergency',['First aid cannot be given to a minor without written consent','The child must sign a consent form first','The first aider must wait for police to grant consent'],'C','A parent or guardian normally consents for a minor, but when none is present in an emergency, consent is implied.',ARC_FA),
  q(BASIC,'After removing gloves, what should a first aider do next?','Wash hands with soap and water for 20 seconds',['Save the gloves to reuse on the next patient','Rinse hands quickly with cold water only','Wipe hands on clothing before leaving'],'D','Gloves can have tiny holes and hands may be contaminated during removal, so hand hygiene always follows glove removal.',AHA_FA),
  q(BASIC,'Why is a breathing barrier with a one-way valve used during rescue breaths?','It shields the rescuer from body fluids',['It doubles the oxygen given with each breath','It removes the need to tilt the head back','It measures how much air enters the lungs'],'A','A barrier device such as a pocket mask protects the rescuer from infection while still allowing effective breaths.',ARC_BLS),
  q(BASIC,'Which person most clearly needs a 911 call?','An adult with chest pressure and trouble breathing',['A child with a scraped knee that stopped bleeding','An adult with a mild headache after a long day','A teen with a small splinter in one finger'],'B','Call for chest pain, breathing problems, unresponsiveness, severe bleeding, seizures, signs of stroke and other life threats.',AHA_FA),
  q(BASIC,'During a head-to-toe check of a responsive injured adult, what should the first aider do first?','Ask permission and explain the check',['Remove all of the person’s clothing','Move the person onto their back','Give the person something to drink'],'C','Explaining the check and getting consent respects the person and reduces anxiety; avoid unnecessary movement during the check.',ARC_FA),
  q(MED,'A person with diabetes is unresponsive, and low blood sugar is suspected. What should the first aider do?','Call 911 and give nothing by mouth',['Pour orange juice into the person’s mouth','Give the person’s insulin injection','Place candy under the person’s tongue'],'D','An unresponsive person cannot swallow safely and may choke. Call 911 and place the person in the recovery position if breathing.',AHA_FA),
  q(MED,'A student faints after seeing blood, recovers quickly and is breathing normally. What is the best care?','Have the student lie down and rest until fully recovered',['Help the student stand up and walk at once','Splash ice water on the student’s face','Give the student a sugary drink right away while lying flat'],'A','Fainting from a nervous system response usually resolves when lying down; call 911 if the person does not recover quickly or is injured.',AHA_FA),
  q(MED,'A woman suddenly develops slurred speech and arm weakness. Why should the first aider note the time symptoms began?','Clot-busting treatment depends on onset time',['The time determines which hospital will bill her','It shows whether she will need CPR soon','It helps decide whether to give her aspirin'],'B','Stroke treatments are time-sensitive, so knowing when the person was last known well guides hospital decisions.',AHA_FA),
  q(MED,'A person feels anxious, is breathing very fast and has tingling in the fingers, with no other illness. What should the first aider do?','Calm the person and coach slower breathing',['Have the person breathe into a sealed plastic bag','Give rescue breaths every 6 seconds','Give the person an epinephrine auto-injector'],'C','Anxiety-driven hyperventilation is eased by reassurance and slow breathing; a paper or plastic bag is no longer recommended.',ARC_FA),
  q(MED,'A toddler with a high fever has a brief seizure and then becomes sleepy. Which action is correct?','Protect the child and get medical care',['Place the child in an ice-water bath','Put a spoon between the child’s teeth','Hold the child’s arms and legs still'],'D','Febrile seizures are frightening but usually brief. Do not restrain the child or put anything in the mouth, and seek medical evaluation.',ARC_FA),
  q(MED,'A person who has epilepsy has a seizure. Which situation requires calling 911?','The seizure lasts longer than 5 minutes',['The person has a known seizure disorder','The person is sleepy afterward','The seizure lasts about 1 minute'],'A','Call 911 for a seizure over 5 minutes, repeated seizures, a first seizure, injury, pregnancy, diabetes, or a seizure in water.',AHA_FA),
  q(MED,'A man has chest discomfort that eases with rest but returns whenever he climbs stairs. What is this most likely?','Angina from reduced heart blood flow',['Heartburn from eating too quickly','A collapsed lung caused by exertion','Muscle strain from climbing the stairs'],'B','Angina occurs when the heart needs more oxygen than narrowed arteries can deliver; pain lasting more than a few minutes may be a heart attack.',DHO),
  q(MED,'A person has mild hives and itching after eating peanuts but no trouble breathing. What should the first aider do?','Help with an antihistamine and watch closely',['Give the epinephrine auto-injector immediately','Have them eat more peanuts to build tolerance','Apply a tourniquet above the elbow'],'C','Mild reactions may be treated with an antihistamine, but any breathing trouble or swelling of the face means anaphylaxis needing epinephrine.',AHA_FA),
  q(MED,'Several people in a garage feel dizzy after paint fumes build up. What is the first priority?','Move everyone to fresh air',['Give each person a glass of milk','Have them lie down in the garage','Induce vomiting in each person'],'D','For inhaled poisons, remove people from the source to fresh air, then call 911 or Poison Control for guidance.',AHA_FA),
  q(MED,'Which finding most suggests dehydration in an adult?','Dark urine, dry mouth, dizziness',['Clear urine and moist, pink lips','A slow pulse and warm, flushed skin','Frequent urination and thirst for sweets'],'A','Fluid loss reduces urine output and blood volume, causing dark urine, dry mucous membranes and dizziness when standing.',DHO),
  q(INJ,'A piece of metal is stuck in a worker’s eye. How should the first aider care for it?','Stabilize the object and cover both eyes',['Pull the object out gently with tweezers','Rinse the eye forcefully until it comes out','Have the worker rub the eye to dislodge it'],'B','Do not remove an impaled object. Covering both eyes reduces eye movement, since the eyes move together.',ARC_FA),
  q(INJ,'A tourniquet has been applied to a leg. What should the first aider do next?','Note the time and leave it in place',['Loosen it every 5 minutes to check bleeding','Remove it once the bleeding slows','Cover it with clothing so it is not seen'],'C','Leave the tourniquet on and record the time so hospital staff know how long blood flow has been stopped.',AHA_FA),
  q(INJ,'A high school player has signs of a concussion during a game. When can the player return to play?','Not the same day; only after medical clearance',['After 15 minutes if the headache goes away','Immediately if the player feels fine','At halftime if the player can jog'],'D','A second impact before the brain heals can cause serious injury, so a player with a suspected concussion is removed for the day.',AHA_FA),
  q(INJ,'A person has a painful rib injury after a fall and breathes shallowly. What can a first aider do to ease breathing?','Have them hold a pillow against the chest',['Wrap tape tightly around the entire chest','Have the person lie flat on the injured side','Encourage the person to hold their breath'],'A','Gentle support reduces pain with breathing. Tight wrapping restricts breathing and is not recommended.',ARC_FA),
  q(INJ,'A worker touched a high-voltage line and has a burn on one hand and another on one foot. Why is this serious?','Current crossed the body and the heart',['The burns are always minor and superficial','Electricity only affects the skin it touches','The burns will heal faster than other burns'],'B','Entry and exit wounds show the current’s path. Internal damage and cardiac arrest are possible, so call 911 once the power is off.',ARC_FA),
  q(INJ,'Dry chemical powder is spilled on a person’s skin. What should be done first?','Brush off the powder, then flush with water',['Pour water on it immediately without brushing','Cover it with a thick layer of ointment','Wrap it tightly with a dressing'],'C','Water can activate some dry chemicals, so brush them off first and then flush with running water.',AHA_FA),
  q(INJ,'A child has a scraped knee with dirt in the wound. Which care is recommended?','Wash with running water and soap, then cover',['Pour hydrogen peroxide into the wound repeatedly','Leave the dirt so a scab can form over it','Seal the wound with tape over the dirt'],'D','Cleaning with running water removes dirt and lowers infection risk. A clean dressing or bandage then protects the wound.',AHA_FA),
  q(INJ,'An athlete’s shoulder appears dislocated after a fall. What should the first aider do?','Support the arm as found and get medical care',['Pull the arm firmly to put it back in place','Have the athlete keep playing to loosen it','Rotate the arm until the shoulder pops'],'A','Attempting to reduce a dislocation can damage nerves and vessels. Immobilize it as found and apply cold.',ARC_FA),
  q(INJ,'A person has heavy bleeding from a wound where a tourniquet cannot be used, and a hemostatic dressing is available. How should it be used?','Pack it in and press firmly',['Lay it loosely on top without pressure','Use it only after the bleeding stops','Soak it in water before applying it'],'B','Hemostatic dressings contain agents that speed clotting but still require firm, direct pressure to work.',AHA_FA),
  q(ENV,'A runner has painful leg muscle spasms after a race in the heat but is alert and sweating. What is the best care?','Rest somewhere cool and sip electrolytes',['Plunge the runner into an ice bath','Give salt tablets with no fluids','Have the runner keep running to stretch'],'C','Heat cramps respond to rest, cooling, gentle stretching and fluids with electrolytes; watch for signs of heat exhaustion.',AHA_FA),
  q(ENV,'A bee stinger is left in the skin. How should it be removed?','Scrape it out quickly with a card',['Squeeze it out with your fingers','Leave it in until a doctor removes it','Burn the area to destroy the venom'],'D','Remove the stinger quickly by scraping; speed matters more than technique. Then wash the area and apply cold.',ARC_FA),
  q(ENV,'A hiker is shivering, cold and wet but alert. What should the first aider do?','Shelter, remove wet clothes, wrap in blankets',['Rub the arms and legs vigorously to warm them','Give the hiker an alcoholic drink to warm up','Put the hiker in a hot bath immediately'],'A','Mild hypothermia is treated by preventing further heat loss and gently rewarming; alcohol and rough handling are harmful.',AHA_FA),
  q(ENV,'A child pulled from a pool coughs, then seems fine. Why should the child still receive medical evaluation?','Breathing trouble can appear hours later',['The child must be tested for infection','Pool chemicals always cause burns','It is required before the child can swim again'],'B','Water in the lungs can cause delayed breathing trouble, so anyone who needed rescue from drowning should be evaluated.',AHA_FA)
 ],5101)
};
